package org.formasaloido;

import java.math.*;import java.util.*;import java.util.regex.*;

/** Bounded sample algebra and trigonometry. No computer-algebra service or free-form solver. */
final class MathAdvanced {
 static String resultSpeech(String value){if(value.startsWith("≈ "))return "aproximadamente "+MathLesson.number(value.substring(2));if(value.equals("Sin solución")||value.equals("Infinitas soluciones"))return value;List<String> words=new ArrayList<>();for(String t:lex(value))words.add(word(t));return String.join(", ",words);}
 static final class Result {String expression,result,reading,structure;final List<String> tokens=new ArrayList<>(),steps=new ArrayList<>();}
 static boolean accepts(String s){return s!=null&&(Pattern.compile("[a-zA-Zπ=]").matcher(s).find());}
 static String clean(String s){if(s==null||s.length()>160)throw new IllegalArgumentException("Máximo 160 caracteres.");return s.replace('−','-').replace('×','*').replace('÷','/').replace("²","^2").replace("³","^3").replace("π","pi").replace(',','.').toLowerCase(Locale.ROOT);}
 static List<String> lex(String text){List<String> out=new ArrayList<>();Matcher m=Pattern.compile("[0-9]+(?:\\.[0-9]+)?|[a-z]+|[()+*/^=:-]").matcher(text);int end=0;while(m.find()){if(!text.substring(end,m.start()).trim().isEmpty())throw new IllegalArgumentException("Símbolo no admitido.");String t=m.group();if(Character.isDigit(t.charAt(0))&&t.replace(".","").length()>12)throw new IllegalArgumentException("Cada número admite hasta doce cifras.");out.add(t);end=m.end();if(out.size()>64)throw new IllegalArgumentException("Máximo 64 símbolos.");}if(!text.substring(end).trim().isEmpty()||out.isEmpty())throw new IllegalArgumentException("Expresión no admitida.");return out;}
 static String word(String t){switch(t){case "x":return "incógnita equis";case "=":return "igual a";case "sin":case "sen":return "seno de";case "cos":return "coseno de";case "tan":return "tangente de";case "sqrt":return "raíz cuadrada de";case "pi":return "pi";case "rad":return "modo radianes";case "deg":case "grad":return "modo grados";case ":":return "";default:return MathLesson.symbol(t);}}
 static MathLesson.Rational q(long n){return new MathLesson.Rational(BigInteger.valueOf(n),BigInteger.ONE);}
 static final class Poly {
  final MathLesson.Rational[] c=new MathLesson.Rational[5];Poly(){Arrays.fill(c,q(0));}static Poly constant(MathLesson.Rational r){Poly p=new Poly();p.c[0]=r;return p;}static Poly x(){Poly p=new Poly();p.c[1]=q(1);return p;}
  Poly combine(String op,Poly b){Poly out=new Poly();if(op.equals("+")||op.equals("-")){for(int i=0;i<5;i++)out.c[i]=c[i].apply(op,b.c[i]);}else if(op.equals("*")){for(int i=0;i<5;i++)for(int j=0;j<5;j++)if(c[i].n.signum()!=0&&b.c[j].n.signum()!=0){if(i+j>4)throw new IllegalArgumentException("Los ejemplos algebraicos admiten grado hasta cuatro.");out.c[i+j]=out.c[i+j].apply("+",c[i].apply("*",b.c[j]));}}else{for(int i=1;i<5;i++)if(b.c[i].n.signum()!=0)throw new IllegalArgumentException("La división algebraica admite únicamente un denominador constante.");for(int i=0;i<5;i++)out.c[i]=c[i].apply("/",b.c[0]);}return out;}
  Poly power(int n){if(n<0||n>4)throw new IllegalArgumentException("Potencias algebraicas enteras de cero a cuatro.");Poly p=constant(q(1));for(int i=0;i<n;i++)p=p.combine("*",this);return p;}
  String text(){StringBuilder s=new StringBuilder();for(int i=4;i>=0;i--){MathLesson.Rational v=c[i];if(v.n.signum()==0)continue;boolean negative=v.n.signum()<0;s.append(s.length()==0?(negative?"-":""):(negative?" - ":" + "));MathLesson.Rational abs=new MathLesson.Rational(v.n.abs(),v.d);if(i==0||!abs.toString().equals("1"))s.append(abs).append(i>0?" * ":"");if(i>0)s.append('x');if(i>1)s.append('^').append(i);}return s.length()==0?"0":s.toString();}
  String speech(){List<String> parts=new ArrayList<>();for(String t:lex(text()))parts.add(word(t));return String.join(", ",parts);}
 }
 static final class Algebra {
  final List<String> t;final List<String> steps;int pos,depth;Algebra(String s,List<String> steps){t=lex(s);this.steps=steps;}
  boolean take(String s){if(pos<t.size()&&t.get(pos).equals(s)){pos++;return true;}return false;}
  Poly parse(){Poly p=sum();if(pos!=t.size())throw new IllegalArgumentException("Símbolo algebraico inesperado: "+t.get(pos));return p;}
  Poly sum(){Poly p=product();while(pos<t.size()&&(t.get(pos).equals("+")||t.get(pos).equals("-"))){String op=t.get(pos++);Poly b=product(),old=p;p=p.combine(op,b);step("Reunimos términos semejantes",old,op,b,p);}return p;}
  void step(String name,Poly a,String op,Poly b,Poly result){if(steps.size()<40)steps.add(name+": "+a.speech()+", "+word(op)+", "+b.speech()+". Obtenemos: "+result.speech()+".");}
  Poly product(){Poly p=unary();while(pos<t.size()){String op=t.get(pos);boolean implicit=op.equals("x")||op.equals("(");if(!implicit&&!op.equals("*")&&!op.equals("/"))break;if(!implicit)pos++;else op="*";Poly b=unary(),old=p;p=p.combine(op,b);step(op.equals("*")?"Aplicamos la propiedad distributiva y reunimos términos":"Dividimos cada coeficiente por la constante",old,op,b,p);}return p;}
  Poly unary(){if(++depth>16)throw new IllegalArgumentException("Demasiados niveles.");try{if(take("-"))return constantNeg(unary());if(take("+"))return unary();Poly p=primary();if(take("^")){if(pos>=t.size()||!t.get(pos).matches("[0-4]"))throw new IllegalArgumentException("Exponente algebraico de cero a cuatro.");int n=Integer.parseInt(t.get(pos++));Poly old=p;p=p.power(n);steps.add("Desarrollamos la potencia "+MathLesson.cardinal(n)+" de "+old.speech()+". Obtenemos "+p.speech()+".");}return p;}finally{depth--;}}
  Poly constantNeg(Poly p){return Poly.constant(q(-1)).combine("*",p);}
  Poly primary(){if(take("(")){Poly p=sum();if(!take(")"))throw new IllegalArgumentException("Falta cerrar paréntesis.");return p;}if(take("x"))return Poly.x();if(pos>=t.size()||!t.get(pos).matches("[0-9]+(?:\\.[0-9]+)?"))throw new IllegalArgumentException("Sólo se admite la incógnita equis y números.");return Poly.constant(MathLesson.Rational.parse(t.get(pos++)));}
 }
 static Result create(String input){String s=clean(input);Result r=new Result();r.expression=s;List<String> raw=lex(s);for(String t:raw){String word=word(t);if(!word.isEmpty())r.tokens.add(word);}r.reading=String.join(", ",r.tokens);
  if(s.matches(".*\\b(sin|sen|cos|tan|sqrt|pi|rad|deg|grad)\\b.*"))return trig(r,s);
  int equal=s.indexOf('=');if(equal>=0){if(equal!=s.lastIndexOf('='))throw new IllegalArgumentException("Usa una sola igualdad.");Poly left=new Algebra(s.substring(0,equal),r.steps).parse(),right=new Algebra(s.substring(equal+1),r.steps).parse();Poly delta=left.combine("-",right);for(int i=2;i<5;i++)if(delta.c[i].n.signum()!=0)throw new IllegalArgumentException("La resolución guiada admite ecuaciones lineales. Puedes desarrollar polinomios hasta grado cuatro sin igualdad.");r.steps.add("Pasamos todos los términos al primer miembro restando el segundo miembro en ambos lados: "+delta.speech()+", igual a cero.");MathLesson.Rational a=delta.c[1],b=delta.c[0];if(a.n.signum()==0){r.result=b.n.signum()==0?"Infinitas soluciones":"Sin solución";r.steps.add(b.n.signum()==0?"Queda cero igual a cero. Cualquier valor de equis satisface la igualdad.":"Queda una constante distinta de cero igual a cero. Ningún valor de equis satisface la igualdad.");}else{MathLesson.Rational neg=new MathLesson.Rational(b.n.negate(),b.d),solution=neg.apply("/",a);r.steps.add("Antes: "+delta.speech()+", igual a cero. Cambio: restamos "+b.speech()+" en ambos miembros. Motivo: conservar la igualdad y dejar el término con equis solo. Ahora: "+a.speech()+" por equis, igual a "+neg.speech()+".");r.steps.add("Antes: "+a.speech()+" por equis, igual a "+neg.speech()+". Cambio: dividimos ambos miembros por "+a.speech()+". Motivo: su coeficiente no es cero y queremos una sola equis. Ahora: equis igual a "+solution.speech()+".");r.result="x = "+solution;r.steps.add("Comprobación: al sustituir este valor en la diferencia de los dos miembros obtenemos "+a.apply("*",solution).apply("+",b).speech()+".");}r.structure="Ecuación con miembro izquierdo y miembro derecho separados por la igualdad. "+r.reading;
  }else{Poly p=new Algebra(s,r.steps).parse();r.result=p.text();if(r.steps.isEmpty())r.steps.add("Polinomio reducido: "+p.speech()+".");r.structure="Expresión algebraica con la incógnita equis. "+r.reading;}return r;
 }
 static final class Trig {
  final List<String> t;final List<String> steps;final boolean radians;int pos,depth;
  Trig(String s,boolean rad,List<String> out){t=lex(s);radians=rad;steps=out;}
  boolean take(String s){if(pos<t.size()&&t.get(pos).equals(s)){pos++;return true;}return false;}
  double parse(){double v=sum();if(pos!=t.size())throw new IllegalArgumentException("Símbolo trigonométrico inesperado.");return finite(v);}
  double finite(double n){if(!Double.isFinite(n)||Math.abs(n)>1e12)throw new IllegalArgumentException("El valor trigonométrico excede el intervalo admitido.");return n;}
  double sum(){double n=product();while(pos<t.size()&&(t.get(pos).equals("+")||t.get(pos).equals("-"))){String op=t.get(pos++);double b=product();n=finite(op.equals("+")?n+b:n-b);}return n;}
  double product(){double n=unary();while(pos<t.size()&&(t.get(pos).equals("*")||t.get(pos).equals("/"))){String op=t.get(pos++);double b=unary();if(op.equals("/")&&b==0)throw new IllegalArgumentException("División entre cero.");n=finite(op.equals("*")?n*b:n/b);}return n;}
  double unary(){if(++depth>16)throw new IllegalArgumentException("Demasiados niveles.");try{if(take("-"))return -unary();if(take("+"))return unary();double n=primary();if(take("^")){double exponent=unary();if(Math.abs(exponent)>12||exponent!=Math.rint(exponent))throw new IllegalArgumentException("Exponente entero de menos doce a doce.");if(n==0&&exponent==0)throw new IllegalArgumentException("Cero elevado a cero no se define en este taller.");n=finite(Math.pow(n,exponent));}return n;}finally{depth--;}}
  double primary(){if(take("(")){double n=sum();if(!take(")"))throw new IllegalArgumentException("Falta cerrar paréntesis.");return n;}if(take("pi"))return Math.PI;if(pos>=t.size())throw new IllegalArgumentException("Falta un valor.");String fn=t.get(pos++);if(fn.matches("[0-9]+(?:\\.[0-9]+)?"))return finite(Double.parseDouble(fn));if(!Arrays.asList("sin","sen","cos","tan","sqrt").contains(fn)||!take("("))throw new IllegalArgumentException("Funciones disponibles: sin, sen, cos, tan y sqrt, con paréntesis.");double arg=sum();if(!take(")"))throw new IllegalArgumentException("Falta cerrar la función.");double angle=radians?arg:Math.toRadians(arg),value;if(fn.equals("sqrt")){if(arg<0)throw new IllegalArgumentException("Raíz de un número negativo: fuera del taller de números reales.");value=Math.sqrt(arg);}else if(fn.equals("tan")){if(Math.abs(Math.cos(angle))<1e-12)throw new IllegalArgumentException("La tangente no está definida en ese ángulo.");value=Math.tan(angle);}else value=fn.equals("cos")?Math.cos(angle):Math.sin(angle);if(Math.abs(value)<1e-14)value=0;steps.add(word(fn)+" "+MathLesson.number(decimal(arg))+(fn.equals("sqrt")?"":radians?" radianes":" grados")+". Aproximación: "+MathLesson.number(decimal(value))+".");return finite(value);}
 }
 static String decimal(double n){return BigDecimal.valueOf(n==0?0:n).setScale(10,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();}
 static Result trig(Result r,String s){boolean radians=s.startsWith("rad:");if(s.startsWith("rad:")||s.startsWith("deg:"))s=s.substring(4);else if(s.startsWith("grad:"))s=s.substring(5);r.steps.add(radians?"Modo radianes. Pi radianes equivale a ciento ochenta grados.":"Modo grados. Una vuelta completa equivale a trescientos sesenta grados.");double value=new Trig(s,radians,r.steps).parse();r.result="≈ "+decimal(value);r.steps.add("Resultado aproximado, mostrado con hasta diez decimales: "+MathLesson.number(decimal(value))+". Se anuncia aproximado incluso cuando coincide con un valor exacto conocido.");r.structure=(radians?"Ángulos en radianes. ":"Ángulos en grados. ")+r.reading;return r;}
}
